Definition apb_cells (w : Z) : list (Z * nat * Z) :=
  [(0x1214c8, 8%nat, 0x10f750); (0x1214d0, 8%nat, 0x109fc4); (0x121600, 8%nat, 0x111ab4); (0x121608, 8%nat, 0x111eb8);
   (0x12d7b8, 8%nat, 0x7fff8000); (0x12e498, 1%nat, 1); (0x12e499, 1%nat, 1); (0x1bf33c, 1%nat, 1);
   (0x123fe0, 4%nat, 5);          (* [comment removed for export] *)
   (0x124000, 8%nat, 0x682300);   (* [comment removed for export] *)
   (0x124008, 8%nat, w);          (* [comment removed for export] *)
   (0x124040, 8%nat, 1024);       (* [comment removed for export] *)
   (0x12406c, 4%nat, 0xffffffff); (* [comment removed for export] *)
   (0x124070, 4%nat, 0xffffffff); (* [comment removed for export] *)
   (0x7fffaa58, 8%nat, 0); (0x7fffaa60, 8%nat, 0); (0x800c83e0, 8%nat, 0)]%Z.   (* [comment removed for export] *)

Record apbH (mem : word -> option byte) (sp : word) (w can : Z) : Prop := APBH {
  Psp16  : bv_unsigned sp mod 16 = 0;
  PspLo  : ASP_LO <= bv_unsigned sp;
  PspHi  : bv_unsigned sp <= ASP_HI;
  Pstk   : stk_ok RSEGS mem sp 3400;
  Pimg   : forall i, 0x10000 <= i < 0x4e000 -> mem (Z_to_bv 64 i) = None;
  Pgot   : forall i, 0x119000 <= i < 0x121000 -> mem (Z_to_bv 64 i) = None;
  Pcells : cells_ok mem (apb_cells w);
  Pcan   : rdn RSEGS mem (Z_to_bv 64 0x681830) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 can));
  Pcan64 : 0 <= can < 2 ^ 64;
  Psh0   : forall a, 2147450880 + (bv_unsigned sp - 4096) / 8 <= a < 2147450880 + bv_unsigned sp / 8 ->
             mem (Z_to_bv 64 a) = Some (Z_to_bv 8 0) }.

Definition apb_post (regs : bvmap 5 word) (mem rom : word -> option byte) (sp : word) (w : Z) : Prop :=
  exists regs' mem',
    msteps RSEGS (mkst regs (Z_to_bv 64 0x0a43f4) mem rom) (mkst regs' (Z_to_bv 64 0x0a4348) mem' rom)
    /\ keeps_cs regs regs'
    /\ frame_mod mem mem' [(Z_to_bv 64 (bv_unsigned sp - 3400), 3400); (Z_to_bv 64 0x123fe0, 4);
                          (Z_to_bv 64 0x124008, 8); (Z_to_bv 64 w, 2)]
    /\ rdn RSEGS mem' (Z_to_bv 64 w) 2 = Some [Z_to_bv 8 0x30; Z_to_bv 8 0x0a]
    /\ rdn RSEGS mem' (Z_to_bv 64 0x124008) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (w + 2)))
    /\ rdn RSEGS mem' (Z_to_bv 64 0x123fe0) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 5)).

