(* [comment removed for export] *)
Definition apb_kn (w : Z) : list kentry :=
  [KAlign (EVar 0) 16; KRange (EVar 0) ASP_LO ASP_HI;
   KWr (SA (EVar 0) (-3400)) 3400;
   KImg 0x10000 0x4e000; KImg 0x119000 0x121000;
   KWord (SA (ELit 0) 0x681830) 8 (EVar 1);
   KWr (SA (ELit 0) 0x123fe0) 232; KWr (SA (ELit 0) 0x681f00) 1024;
   KRange ap1_shx ASH_LO ASH_HI; KZero (SA ap1_shx 0) (ELit 8)]%Z
  ++ kn_cells (apb_cells w).

Definition apb_regions (w : Z) : list sregion :=
  [(SA (EVar 0) (-3400), 3400); (SA (ELit 0) 0x123fe0, 4); (SA (ELit 0) 0x124008, 8); (SA (ELit 0) w, 2)].

Definition apb_run (w : Z) :=
  sym_exec RSEGS FUEL1 true STOPS1 scrA (SS 0x0a43f4 ap1_sr [] (apb_kn w) 34) [].

