Definition resP0 := Eval vm_compute in (apb_run 0x681f00).
Definition carP0 := Eval vm_compute in (carry (s_log (fst (fst resP0))) (apb_kn 0x681f00) []).
Definition resP1 := Eval vm_compute in (apb_run 0x681f02).
Definition carP1 := Eval vm_compute in (carry (s_log (fst (fst resP1))) (apb_kn 0x681f02) []).
Definition resP2 := Eval vm_compute in (apb_run 0x681f04).
Definition carP2 := Eval vm_compute in (carry (s_log (fst (fst resP2))) (apb_kn 0x681f04) []).

Ltac run_case res car :=
  lazymatch goal with
  | PH : apbH ?mem ?sp ?w ?can, Hw : _, R1 : getr ?regs 1 = _, R2 : getr _ 2 = _, R11 : getr _ 11 = _ |- apb_post _ _ ?rom _ _ =>
      eapply (apb_case regs mem rom sp w can PH Hw R1 R2 R11
                (fst (fst res)) (snd (fst res)) (snd res) (fst (fst car)) (snd car));
      [ vm_cast_no_check (@eq_refl _ res)
      | reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_cast_no_check (@eq_refl _ car)
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity ]
  end.

Lemma apb_case0 : forall regs mem rom sp can,
  apbH mem sp 0x681f00 can ->
